  'faq.badge': { en: 'Insurance FAQ', hi: 'बीमा FAQ', hinglish: 'Insurance FAQ' },
  'faq.heading': { en: 'Your Insurance Questions, Our Answers', hi: 'आपके बीमा प्रश्न, हमारे उत्तर', hinglish: 'Aapke Insurance Sawal, Humare Jawaab' },
  'faq.description': { en: '36 frequently asked questions about Indian insurance — health, term, motor, claims, and tax benefits. Every answer is as per IRDAI rules.', hi: 'भारतीय बीमे के बारे में 36 अक्सर पूछे जाने वाले प्रश्न — स्वास्थ्य, टर्म, मोटर, क्लेम और कर लाभ। हर उत्तर IRDAI नियमों के अनुसार।', hinglish: '36 frequently asked questions about Indian insurance — health, term, motor, claims, aur tax benefits. Har jawaab IRDAI rules ke according.' },
  'faq.searchPlaceholder': { en: 'Search your insurance question...', hi: 'अपना बीमा प्रश्न खोजें...', hinglish: 'Apna insurance sawal search karein...' },
  'faq.clear': { en: 'Clear', hi: 'हटाएं', hinglish: 'Clear' },
  'faq.resultsFound': { en: 'results found', hi: 'परिणाम मिले', hinglish: 'results mile' },
  'faq.resultFound': { en: 'result found', hi: 'परिणाम मिला', hinglish: 'result mila' },
  'faq.noResults': { en: 'No FAQs found. Try a different search or select a category.', hi: 'कोई FAQ नहीं मिला। अलग खोज आज़माएं या श्रेणी चुनें।', hinglish: 'Koi FAQ nahi mila. Search change karein ya category select karein.' },
