  'trust.tips.tip1': { en: 'Always read the policy document before signing', hi: 'हस्ताक्षर करने से पहले हमेशा पॉलिसी दस्तावेज़ पढ़ें', hinglish: 'Hamesha policy document padhein sign karne se pehle' },
  'trust.tips.tip2': { en: 'Verify agent IRDAI license on official portal', hi: 'एजेंट का IRDAI लाइसेंस आधिकारिक पोर्टल पर सत्यापित करें', hinglish: 'Agent ka IRDAI license official portal pe verify karein' },
  'trust.tips.tip3': { en: 'Use free-look period (15-30 days) to cancel if not satisfied', hi: 'संतुष्ट न होने पर फ्री-लुक पीरियड (15-30 दिन) में रद्द करें', hinglish: 'Free-look period (15-30 din) mein cancel karein agar satisfied nahi ho' },
