  'insureGPT.feature.language.title': { en: 'Speaks Your Language', hi: 'आपकी भाषा बोलता है', hinglish: 'Aapki Bhasha Bola Hai' },
  'insureGPT.feature.language.text': { en: "Full support in Hinglish, Hindi & English. No language barrier — ask in the language you're most comfortable with.", hi: 'हिंग्लिश, हिंदी और अंग्रेज़ी में पूर्ण समर्थन। कोई भाषा बाधा नहीं — जिस भाषा में सहज हों, पूछें।', hinglish: 'Hinglish, Hindi & English mein full support. Koi language barrier nahi — jis bhasha mein comfortable hain, poochiye.' },
