  'insureGPT.feature.irdai.title': { en: 'IRDAI-Verified & Unbiased', hi: 'IRDAI-सत्यापित और निष्पक्ष', hinglish: 'IRDAI-Verified & Unbiased' },
  'insureGPT.feature.irdai.text': { en: 'Licensed POSP (IP429834). Every recommendation follows IRDAI guidelines. Zero mis-selling guarantee — your free-look period is always protected.', hi: 'लाइसेंस प्राप्त POSP (IP429834)। हर सिफारिश IRDAI दिशानिर्देशों का पालन करती है। शून्य गलत बिक्री गारंटी — आपका फ्री-लुक पीरियड हमेशा संरक्षित।', hinglish: 'Licensed POSP (IP429834). Har recommendation IRDAI guidelines ke according. Zero mis-selling guarantee — free-look period hamesha protected.' },
  'insureGPT.feature.tax.title': { en: 'Maximize Tax Savings', hi: 'कर बचत को अधिकतम करें', hinglish: 'Tax Savings Maximize Karein' },
  'insureGPT.feature.tax.text': { en: 'Automatically optimizes Section 80D deductions — save up to ₹75,000/year on health insurance premiums for self and senior citizen parents.', hi: 'स्वचालित रूप से धारा 80D कटौती को अनुकूलित करता है — स्वयं और वरिष्ठ नागरिक माता-पिता के स्वास्थ्य बीमा प्रीमियम पर ₹75,000/वर्ष तक की बचत।', hinglish: 'Automatically Section 80D deductions optimize karta hai — self aur senior citizen parents ke health insurance premium pe ₹75,000/year tak bachat.' },
  'insureGPT.feature.claims.title': { en: 'End-to-End Claim Support', hi: 'अंत-से-अंत क्लेम सहायता', hinglish: 'End-to-End Claim Support' },
  'insureGPT.feature.claims.text': { en: 'From claim filing to final settlement, our 97% success-rate team guides you through documentation, cashless approvals, and escalations.', hi: 'क्लेम दाखिल से अंतिम निपटान तक, हमारी 97% सफलता-दर टीम दस्तावेज़ीकरण, कैशलेस अनुमोदन और स्नातन में आपका मार्गदर्शन करती है।', hinglish: 'Claim filing se final settlement tak, hamari 97% success-rate team documentation, cashless approvals aur escalations mein guide karti hai.' },
