  // ── WhyUs Section (detailed features) ──────────────────────────────────────
  'whyUs.feature.ai.title': { en: 'AI-Powered Recommendations', hi: 'AI-संचालित सिफारिशें', hinglish: 'AI-Powered Recommendations' },
  'whyUs.feature.ai.desc': { en: '51+ insurers analyzed in <30 seconds. Personalized for YOUR age, city, and health profile. Zero bias, zero mis-selling.', hi: '30 सेकंड से कम में 51+ बीमाकर्ताओं का विश्लेषण। आपकी आयु, शहर और स्वास्थ्य प्रोफ़ाइल के लिए व्यक्तिगत। शून्य पक्षपात, शून्य गलत बिक्री।', hinglish: '51+ insurers ka analysis 30 second mein. Aapki age, city aur health profile ke liye personalized. Koi bias nahi, koi mis-selling nahi.' },
  'whyUs.feature.irdai.title': { en: 'IRDAI Verified POSP', hi: 'IRDAI सत्यापित POSP', hinglish: 'IRDAI Verified POSP' },
  'whyUs.feature.irdai.desc': { en: 'POSP Code IP429834. Every recommendation follows IRDAI guidelines. Your free-look period is always protected.', hi: 'POSP कोड IP429834। हर सिफारिश IRDAI दिशानिर्देशों का पालन करती है। आपका फ्री-लुक पीरियड हमेशा संरक्षित है।', hinglish: 'POSP Code IP429834. Har recommendation IRDAI guidelines ke compliant hai. Aapka free-look period hamesha protected hai.' },
  'whyUs.feature.jargon.title': { en: 'No Jargon, No Confusion', hi: 'कोई जटिल शब्द नहीं, कोई भ्रम नहीं', hinglish: 'No Jargon, No Confusion' },
  'whyUs.feature.jargon.desc': { en: 'Complex insurance terms explained in simple Hinglish. No hidden conditions, no sales pressure. Samjho aur khareedo.', hi: 'जटिल बीमा शब्दावली सरल हिंग्लिश में समझाई गई। कोई छिपी शर्तें नहीं, कोई बिक्री दबाव नहीं। समझो और खरीदो।', hinglish: 'Insurance ki complex terms aasan Hinglish mein samjhate hain. Koi hidden conditions nahi, koi sales pressure nahi.' },
  'whyUs.feature.claims.title': { en: 'Easy Claims Assistance', hi: 'आसान क्लेम सहायता', hinglish: 'Easy Claims Assistance' },
  'whyUs.feature.claims.desc': { en: '97% claim support rate. Free documentation help, cashless claim guidance, and WhatsApp support 24/7.', hi: '97% क्लेम सहायता दर। मुफ़्त दस्तावेज़ सहायता, कैशलेस क्लेम मार्गदर्शन, और WhatsApp सहायता 24/7।', hinglish: '97% claim support rate. Muft documentation help, cashless claim guidance, aur WhatsApp support 24/7.' },
  'whyUs.promise.samePrice': { en: 'Same Price as Insurer — You NEVER pay more. Premium is exactly what the insurer charges.', hi: 'Insurer जैसा ही मूल्य — आप कभी अधिक भुगतान नहीं करते। प्रीमियम ठीक वही है जो बीमाकर्ता चार्ज करता है।', hinglish: 'Same Price as Insurer — Aap kabhi zyada pay nahi karte. Premium wahi hai jo insurer charge karta hai.' },
  'whyUs.promise.freeClaim': { en: 'Free Claim Support — From filing to settlement. We handle documentation, follow-ups, and escalations.', hi: 'मुफ़्त क्लेम सहायता — दाखिल से निपटान तक। हम दस्तावेज़ीकरण, अनुवर्ती और स्नातन संभालते हैं।', hinglish: 'Muft Claim Support — Filing se settlement tak. Hum documentation, follow-ups aur escalations sambhalte hain.' },
  'whyUs.promise.noCancel': { en: 'No Cancellation Fees — Switch or cancel anytime. No hidden charges, no penalty.', hi: 'कोई रद्दीकरण शुल्क नहीं — कभी भी स्विच या रद्द करें। कोई छिपे शुल्क नहीं, कोई दंड नहीं।', hinglish: 'Koi Cancellation Fees Nahi — Kabhi bhi switch ya cancel karein. Koi hidden charges nahi, koi penalty nahi.' },
  'whyUs.promise.noDataSell': { en: 'Zero Data Selling — Your personal and medical data is NEVER shared with third parties.', hi: 'डेटा बिक्री नहीं — आपका व्यक्तिगत और चिकित्सा डेटा कभी तीसरे पक्ष के साथ साझा नहीं किया जाता।', hinglish: 'Data Bechna Nahi — Aapka personal aur medical data kabhi third parties ke saath share nahi hota.' },

