  // ── FAQ Items ─────────────────────────────────────────────────────────────────
  'faq.q1': { en: 'What makes Paliwal Secure different from other insurance platforms?', hi: 'Paliwal Secure dusre insurance platforms se kaise alag hai?', hinglish: 'Paliwal Secure dusre insurance platforms se kaise alag hai?' },
  'faq.a1': { en: "We're India's only AI-powered insurance advisor with InsureGPT. We compare 51+ IRDAI insurers fairly — no insurer bias, no hidden charges. Plus, we provide claim support from filing to settlement.", hi: 'Hum India ke ekmatra AI-powered insurance advisor hain InsureGPT ke saath. Hum 51+ IRDAI insurers ki fair comparison karte hain — koi insurer bias nahi, koi hidden charges nahi.', hinglish: "Hum India ke ekmatra AI-powered insurance advisor hain InsureGPT ke saath. Hum 51+ IRDAI insurers ki fair comparison karte hain — koi insurer bias nahi, koi hidden charges nahi." },
  'faq.q2': { en: 'Is Paliwal Secure IRDAI registered?', hi: 'Kya Paliwal Secure IRDAI registered hai?', hinglish: 'Kya Paliwal Secure IRDAI registered hai?' },
  'faq.a2': { en: 'Yes! We are IRDAI Registered POSP with code IP429834. All our recommendations are fully compliant with IRDAI guidelines. You can verify our license anytime.', hi: 'Haan! Hum IRDAI Registered POSP hain code IP429834 ke saath. Humari saari recommendations IRDAI guidelines ke fully compliant hain.', hinglish: 'Haan! Hum IRDAI Registered POSP hain code IP429834 ke saath. Humari saari recommendations IRDAI guidelines ke fully compliant hain.' },
  'faq.q3': { en: 'How does InsureGPT AI work?', hi: 'InsureGPT AI kaise kaam karta hai?', hinglish: 'InsureGPT AI kaise kaam karta hai?' },
  'faq.a3': { en: 'InsureGPT uses advanced AI to analyze your needs, compare 51+ insurers, and recommend the best plan — personalized just for you. It considers CSR, coverage, premium, and your specific requirements.', hi: 'InsureGPT advanced AI use karta hai aapki zarooratein analyze karne ke liye, 51+ insurers compare karne ke liye, aur best plan recommend karne ke liye — personally aapke liye.', hinglish: 'InsureGPT advanced AI use karta hai aapki zarooratein analyze karne ke liye, 51+ insurers compare karne ke liye, aur best plan recommend karne ke liye — personally aapke liye.' },
  'faq.q4': { en: 'Will I pay more if I buy through Paliwal Secure?', hi: 'Agar main Paliwal Secure se khareedun toh zyada pay karna padega?', hinglish: 'Kya main Paliwal Secure se khareedne par zyada pay karunga?' },
  'faq.a4': { en: 'Absolutely not! You pay the same premium as buying directly from the insurer. The commission is paid by the insurer, NOT by you. This is standard IRDAI practice.', hi: 'Bilkul nahi! Aap wohi premium pay karte hain jaise directly insurer se khareedte hain. Commission insurer dwara pay kiya jaata hai, aapke dwara nahi.', hinglish: 'Bilkul nahi! Aap wohi premium pay karte hain jaise directly insurer se khareedte hain. Commission insurer dwara pay kiya jaata hai, aapke dwara nahi.' },
  'faq.q5': { en: 'Do you help with insurance claims?', hi: 'Kya aap insurance claims mein madad karte hain?', hinglish: 'Kya aap insurance claims mein madad karte hain?' },
  'faq.a5': { en: 'Yes! We provide end-to-end claim support — from filing the claim to getting it settled. Our 97% claim support rate speaks for itself. Contact us on WhatsApp anytime.', hi: 'Haan! Hum end-to-end claim support dete hain — claim file karne se lekar settle hone tak. Humara 97% claim support rate khud bolta hai.', hinglish: 'Haan! Hum end-to-end claim support dete hain — claim file karne se lekar settle hone tak. Humara 97% claim support rate khud bolta hai.' },
  'faq.q6': { en: 'Can I compare insurance plans for free?', hi: 'Kya main insurance plans free mein compare kar sakta hoon?', hinglish: 'Kya main insurance plans free mein compare kar sakta hoon?' },
  'faq.a6': { en: 'Yes, 100% free! Compare plans, get AI recommendations, and talk to our experts — all at zero cost. No obligation to buy.', hi: 'Haan, 100% free! Plans compare karein, AI recommendations paayein, aur humare experts se baat karein — sab zero cost par.', hinglish: 'Haan, 100% free! Plans compare karein, AI recommendations paayein, aur humare experts se baat karein — sab zero cost par.' },
  'faq.q7': { en: 'What languages do you support?', hi: 'Aap kaun kaun si bhashaen support karte hain?', hinglish: 'Aap kaun kaun si languages support karte hain?' },
  'faq.a7': { en: 'We support English, Hindi, and Hinglish — choose whichever you\'re comfortable with. Our AI and experts understand all three.', hi: 'Hum English, Hindi, aur Hinglish support karte hain — jo bhi comfortable ho woh choose karein.', hinglish: 'Hum English, Hindi, aur Hinglish support karte hain — jo bhi comfortable ho woh choose karein.' },
  'faq.q8': { en: 'How do I contact Paliwal Secure?', hi: 'Paliwal Secure se kaise contact karun?', hinglish: 'Paliwal Secure se kaise contact karun?' },
  'faq.a8': { en: 'WhatsApp us at +91 9257877312 or call directly. We\'re available 24/7 to help you with any insurance query.', hi: 'WhatsApp karein +91 9257877312 par ya directly call karein. Hum 24/7 available hain aapki kisi bhi insurance query ke liye.', hinglish: 'WhatsApp karein +91 9257877312 par ya directly call karein. Hum 24/7 available hain aapki kisi bhi insurance query ke liye.' },

