  // ── How It Works (New Landing) ────────────────────────────────────────
  'howItWorksNew.heading': { en: 'Kaise Kaam Karta Hai', hi: 'कैसे काम करता है', hinglish: 'Kaise Kaam Karta Hai' },
  'howItWorksNew.subheading': { en: 'Smart insurance ke liye sirf 3 simple steps.', hi: 'स्मार्ट इंश्योरेंस के लिए सिर्फ 3 सिंपल स्टेप्स।', hinglish: 'Smart insurance ke liye sirf 3 simple steps.' },
  'howItWorksNew.step1.title': { en: 'Apne Baare Mein Bataiye', hi: 'अपने बारे में बताइए', hinglish: 'Apne Baare Mein Bataiye' },
  'howItWorksNew.step1.desc': { en: '5-6 simple questions answer karein apni family, health, vehicle aur budget ke baare mein. Hamara intelligent system aapki needs ko detail mein samajhta hai.', hi: '5-6 सरल प्रश्नों के उत्तर दें अपने परिवार, स्वास्थ्य, वाहन और बजट के बारे में। हमारा बुद्धिमान सिस्टम आपकी ज़रूरतों को विस्तार से समझता है।', hinglish: '5-6 simple questions answer karein apni family, health, vehicle aur budget ke baare mein. Hamara intelligent system aapki needs ko detail mein samajhta hai.' },
  'howItWorksNew.step2.title': { en: 'InsureGPT Analyze Karega', hi: 'InsureGPT एनालाइज़ करेगा', hinglish: 'InsureGPT Analyze Karega' },
  'howItWorksNew.step2.desc': { en: 'Hamara AI engine 51+ insurers ke hazaron plans ko process karta hai milliseconds mein. Sabse best premium, benefits aur claim settlement metrics scan hote hain.', hi: 'हमारा AI इंजन 51+ बीमाकर्ताओं के हज़ारों प्लान्स को मिलीसेकंड में प्रोसेस करता है। सबसे बेस्ट प्रीमियम, लाभ और क्लेम सेटलमेंट मेट्रिक्स स्कैन होते हैं।', hinglish: 'Hamara AI engine 51+ insurers ke hazaron plans ko process karta hai milliseconds mein. Sabse best premium, benefits aur claim settlement metrics scan hote hain.' },
  'howItWorksNew.step3.title': { en: 'Choose Karein Aur Secure Ho Jaayein', hi: 'चुनें और सुरक्षित हो जाएं', hinglish: 'Choose Karein Aur Secure Ho Jaayein' },
  'howItWorksNew.step3.desc': { en: 'AI ke suggested best plans mein se apna favourite pick karein aur instantly digital policy documents paayein. Safe, Secure aur Super Fast!', hi: 'AI के सुझाए गए बेस्ट प्लान्स में से अपना पसंदीदा चुनें और तुरंत डिजिटल पॉलिसी डॉक्यूमेंट्स पाएं। सुरक्षित, सुरक्षित और सुपर फास्ट!', hinglish: 'AI ke suggested best plans mein se apna favourite pick karein aur instantly digital policy documents paayein. Safe, Secure aur Super Fast!' },

