  'products.travel.desc': { en: 'International trips ke liye global coverage, medical emergencies aur loss protection.', hi: 'अंतर्राष्ट्रीय यात्राओं के लिए ग्लोबल कवरेज, मेडिकल इमरजेंसी और नुकसान सुरक्षा।', hinglish: 'International trips ke liye global coverage, medical emergencies aur loss protection.' },
