  'landing.testimonials.rohan.quote': { en: 'AI recommendations are spot on. Maine pehle agent se baat ki thi but PaliwalSecure ne use better rates aur benefits diye. Total trust! 🚀', hi: 'AI रिकमेंडेशन्स बिल्कुल सही हैं। मैंने पहले एजेंट से बात की थी लेकिन पालीवालसेक्योर ने बेहतर रेट्स और बेनेफिट्स दिए। पूरा भरोसा! 🚀', hinglish: 'AI recommendations are spot on. Maine pehle agent se baat ki thi but PaliwalSecure ne use better rates aur benefits diye. Total trust! 🚀' },
  'landing.testimonials.rohan.name': { en: 'Rohan Kapoor', hi: 'रोहन कपूर', hinglish: 'Rohan Kapoor' },
  'landing.testimonials.rohan.location': { en: 'Bangalore | Reliance Motor', hi: 'बैंगलोर | रिलायंस मोटर', hinglish: 'Bangalore | Reliance Motor' },
  'landing.testimonials.amit.quote': { en: "Finally a platform that doesn't spam! Clean UI, simple process aur honest advice. Mere family ke liye best insurance yahan mila. 💙", hi: 'आखिरकार एक प्लेटफ़ॉर्म जो स्पैम नहीं करता! क्लीन UI, सिंपल प्रोसेस और ईमानदार सलाह। मेरे परिवार के लिए बेस्ट इंश्योरेंस यहाँ मिला। 💙', hinglish: "Finally a platform that doesn't spam! Clean UI, simple process aur honest advice. Mere family ke liye best insurance yahan mila. 💙" },
