  // ── Landing FAQ Section ───────────────────────────────────────────────
  'landing.faq.heading': { en: 'Aksar Pooche Jaane Wale Sawaal', hi: 'अक्सर पूछे जाने वाले सवाल', hinglish: 'Aksar Pooche Jaane Wale Sawaal' },
  'landing.faq.subheading': { en: 'Aapke sawaal, humare AI-powered jawaab.', hi: 'आपके सवाल, हमारे AI-पावर्ड जवाब।', hinglish: 'Aapke sawaal, humare AI-powered jawaab.' },
  'landing.faq.q1': { en: 'InsureGPT AI kaise kaam karta hai?', hi: 'InsureGPT AI कैसे काम करता है?', hinglish: 'InsureGPT AI kaise kaam karta hai?' },
  'landing.faq.a1': { en: 'InsureGPT advanced AI algorithm use karke 51+ insurers ke plans ko analyze karta hai. Aapke needs, family, health, budget ka dhyaan rakhke best plans recommend karta hai.', hi: 'InsureGPT उन्नत AI एल्गोरिदम का उपयोग करके 51+ बीमाकर्ताओं के प्लान का विश्लेषण करता है। आपकी ज़रूरतों, परिवार, स्वास्थ्य, बजट का ध्यान रखकर बेस्ट प्लान रिकमेंड करता है।', hinglish: 'InsureGPT advanced AI algorithm use karke 51+ insurers ke plans ko analyze karta hai. Aapke needs, family, health, budget ka dhyaan rakhke best plans recommend karta hai.' },
  'landing.faq.q2': { en: 'Kya ye recommendations sach mein free hain?', hi: 'क्या ये रिकमेंडेशन्स सच में फ्री हैं?', hinglish: 'Kya ye recommendations sach mein free hain?' },
  'landing.faq.a2': { en: 'Bilkul! InsureGPT AI se recommendations completely free hain. Hum commission earn karte hain insurance company se, hum aapse koi fee nahi lete.', hi: 'बिल्कुल! InsureGPT AI से रिकमेंडेशन्स पूरी तरह फ्री हैं। हम कमीशन इंश्योरेंस कंपनी से कमाते हैं, हम आपसे कोई फीस नहीं लेते।', hinglish: 'Bilkul! InsureGPT AI se recommendations completely free hain. Hum commission earn karte hain insurance company se, hum aapse koi fee nahi lete.' },
  'landing.faq.q3': { en: 'Claims settlement kitni jaldi hoti hai?', hi: 'क्लेम सेटलमेंट कितनी जल्दी होती है?', hinglish: 'Claims settlement kitni jaldi hoti hai?' },
  'landing.faq.a3': { en: 'Humare partner insurers 98% claims ko prioritize karte hain. Digital processing ki wajah se settlement normally 5-7 days mein complete ho jata hai.', hi: 'हमारे पार्टनर इंश्योरर्स 98% क्लेम्स को प्राथमिकता देते हैं। डिजिटल प्रोसेसिंग की वजह से सेटलमेंट आमतौर पर 5-7 दिनों में पूरा हो जाता है।', hinglish: 'Humare partner insurers 98% claims ko prioritize karte hain. Digital processing ki wajah se settlement normally 5-7 days mein complete ho jata hai.' },
  'landing.faq.q4': { en: 'Kya mera data safe hai?', hi: 'क्या मेरा डेटा सेफ है?', hinglish: 'Kya mera data safe hai?' },
  'landing.faq.a4': { en: 'Bilkul! Hamara platform bank-level encryption use karta hai. Aapka personal aur financial data completely protected hai. Hum IRDAI regulated hain aur data privacy laws follow karte hain.', hi: 'बिल्कुल! हमारा प्लेटफ़ॉर्म बैंक-लेवल एन्क्रिप्शन यूज़ करता है। आपका पर्सनल और फाइनेंशियल डेटा पूरी तरह प्रोटेक्टेड है। हम IRDAI रेगुलेटेड हैं और डेटा प्राइवेसी लॉज़ फॉलो करते हैं।', hinglish: 'Bilkul! Hamara platform bank-level encryption use karta hai. Aapka personal aur financial data completely protected hai. Hum IRDAI regulated hain aur data privacy laws follow karte hain.' },
  'landing.faq.q5': { en: 'Premium cost kitna hota hai?', hi: 'प्रीमियम कॉस्ट कितना होता है?', hinglish: 'Premium cost kitna hota hai?' },
  'landing.faq.a5': { en: 'Premium aapke age, health, coverage needs, aur occupation par depend karta hai. InsureGPT AI aapke budget ke according best plans suggest karta hai.', hi: 'प्रीमियम आपकी उम्र, स्वास्थ्य, कवरेज ज़रूरतों और व्यवसाय पर निर्भर करता है। InsureGPT AI आपके बजट के अनुसार बेस्ट प्लान सजेस्ट करता है।', hinglish: 'Premium aapke age, health, coverage needs, aur occupation par depend karta hai. InsureGPT AI aapke budget ke according best plans suggest karta hai.' },
  'landing.faq.q6': { en: 'Kya pre-existing conditions cover hote hain?', hi: 'क्या प्री-एग्जिस्टिंग कंडीशन्स कवर होते हैं?', hinglish: 'Kya pre-existing conditions cover hote hain?' },
  'landing.faq.a6': { en: 'Coverage aapke selected plan aur insurance company par depend karta hai. InsureGPT AI sab options explain karta hai aur best plan suggest karta hai.', hi: 'कवरेज आपके चुने हुए प्लान और इंश्योरेंस कंपनी पर निर्भर करता है। InsureGPT AI सब ऑप्शन एक्सप्लेन करता है और बेस्ट प्लान सजेस्ट करता है।', hinglish: 'Coverage aapke selected plan aur insurance company par depend karta hai. InsureGPT AI sab options explain karta hai aur best plan suggest karta hai.' },
  'landing.faq.q7': { en: 'Mobile app bhi available hai?', hi: 'मोबाइल ऐप भी उपलब्ध है?', hinglish: 'Mobile app bhi available hai?' },
  'landing.faq.a7': { en: 'Haan! PaliwalSecure mobile app iOS aur Android dono par available hai. App se aap quotes, plans, claims, documents - sab kuch manage kar sakte ho easily.', hi: 'हाँ! पालीवालसेक्योर मोबाइल ऐप iOS और Android दोनों पर उपलब्ध है। ऐप से आप कोट्स, प्लान्स, क्लेम्स, डॉक्यूमेंट्स - सब कुछ मैनेज कर सकते हो आसानी से।', hinglish: 'Haan! PaliwalSecure mobile app iOS aur Android dono par available hai. App se aap quotes, plans, claims, documents - sab kuch manage kar sakte ho easily.' },
  'landing.faq.q8': { en: 'Agar mujhe plan nahi pasand aaye to?', hi: 'अगर मुझे प्लान नहीं पसंद आए तो?', hinglish: 'Agar mujhe plan nahi pasand aaye to?' },
  'landing.faq.a8': { en: 'Koi problem nahi! Aapke paas 30 days cooling-off period hota hai. Agar plan aapko pasand nahi aaye to full refund le sakte ho.', hi: 'कोई प्रॉब्लम नहीं! आपके पास 30 दिन कूलिंग-ऑफ पीरियड होता है। अगर प्लान आपको पसंद नहीं आए तो फुल रिफंड ले सकते हो।', hinglish: 'Koi problem nahi! Aapke paas 30 days cooling-off period hota hai. Agar plan aapko pasand nahi aaye to full refund le sakte ho.' },

