  'glossary.term.zeroDep.name': { en: 'Zero Depreciation', hi: 'ज़ीरो डेप्रिसिएशन', hinglish: 'Zero Depreciation' },
  'glossary.term.zeroDep.hindi': { en: 'जीरो डेप्रिसिएशन', hi: 'ज़ीरो डेप्रिसिएशन', hinglish: 'Zero Depreciation' },
  'glossary.term.zeroDep.explanation': { en: 'Car ka pura parts ka bill insurance dega, koi cut nahi', hi: 'कार का पूरा पार्ट्स का बिल इंश्योरेंस देगा, कोई कट नहीं', hinglish: 'Car ka pura parts ka bill insurance dega, koi cut nahi' },
  'glossary.term.zeroDep.example': { en: '₹50,000 ka dent repair — zero dep mein poora pay, normal mein ₹25,000 pay', hi: '₹50,000 का डेंट रिपेयर — ज़ीरो डेप में पूरा पे, नॉर्मल में ₹25,000 पे', hinglish: '₹50,000 ka dent repair — zero dep mein poora pay, normal mein ₹25,000 pay' },
  'glossary.term.zeroDep.category': { en: 'motor', hi: 'motor', hinglish: 'motor' },

  'glossary.term.ncb.name': { en: 'NCB (No Claim Bonus)', hi: 'NCB (क्लेम बोनस)', hinglish: 'NCB (No Claim Bonus)' },
  'glossary.term.ncb.hindi': { en: 'क्लेम बोनस', hi: 'क्लेम बोनस', hinglish: 'Claim Bonus' },
  'glossary.term.ncb.explanation': { en: 'Agar saal bhar koi claim nahi kiya toh next year premium mein discount', hi: 'यदि साल भर कोई क्लेम नहीं किया तो अगले साल प्रीमियम में छूट', hinglish: 'Agar saal bhar koi claim nahi kiya toh next year premium mein discount' },
  'glossary.term.ncb.example': { en: '5 saal no claim = 50% discount, ₹15,000 premium se ₹7,500', hi: '5 साल कोई क्लेम नहीं = 50% छूट, ₹15,000 प्रीमियम से ₹7,500', hinglish: '5 saal no claim = 50% discount, ₹15,000 premium se ₹7,500' },
  'glossary.term.ncb.category': { en: 'motor', hi: 'motor', hinglish: 'motor' },

  'glossary.term.thirdParty.name': { en: 'Third Party Insurance', hi: 'थर्ड पार्टी बीमा', hinglish: 'Third Party Insurance' },
  'glossary.term.thirdParty.hindi': { en: 'थर्ड पार्टी बीमा', hi: 'थर्ड पार्टी बीमा', hinglish: 'Third Party Beema' },
  'glossary.term.thirdParty.explanation': { en: 'Dusre ko hua nuksan ka payment, apna nuksan nahi', hi: 'दूसरे को हुआ नुकसान का भुगतान, अपना नुकसान नहीं', hinglish: 'Dusre ko hua nuksan ka payment, apna nuksan nahi' },
  'glossary.term.thirdParty.example': { en: 'Tumhari car se kisi ko lag gaya — uska ilaaj TP se, tumhara car ka nahi', hi: 'तुम्हारी कार से किसी को लग गया — उसका इलाज TP से, तुम्हारी कार का नहीं', hinglish: 'Tumhari car se kisi ko lag gaya — uska ilaaj TP se, tumhara car ka nahi' },
  'glossary.term.thirdParty.category': { en: 'motor', hi: 'motor', hinglish: 'motor' },

  'glossary.term.comprehensive.name': { en: 'Comprehensive Insurance', hi: 'कॉम्प्रिहेंसिव बीमा', hinglish: 'Comprehensive Insurance' },
  'glossary.term.comprehensive.hindi': { en: 'पूरा बीमा', hi: 'पूरा बीमा', hinglish: 'Poora Beema' },
  'glossary.term.comprehensive.explanation': { en: 'Apna nuksan + dusre ka nuksan dono cover', hi: 'अपना नुकसान + दूसरे का नुकसान दोनों कवर', hinglish: 'Apna nuksan + dusre ka nuksan dono cover' },
  'glossary.term.comprehensive.example': { en: 'Car khisak gayi, tumhari galti — comprehensive mein dono side pay', hi: 'कार खिसक गई, तुम्हारी गलती — कॉम्प्रिहेंसिव में दोनों साइड पे', hinglish: 'Car khisak gayi, tumhari galti — comprehensive mein dono side pay' },
  'glossary.term.comprehensive.category': { en: 'motor', hi: 'motor', hinglish: 'motor' },

  'glossary.term.premium.name': { en: 'Premium', hi: 'प्रीमियम', hinglish: 'Premium' },
