  'glossary.term.premium.explanation': { en: 'Insurance ke liye har saal dene ka paisa', hi: 'बीमा के लिए हर साल देने का पैसा', hinglish: 'Insurance ke liye har saal dene ka paisa' },
  'glossary.term.premium.example': { en: '₹8,000/year car insurance ka premium', hi: '₹8,000/वर्ष कार इंश्योरेंस का प्रीमियम', hinglish: '₹8,000/year car insurance ka premium' },
  'glossary.term.premium.category': { en: 'general', hi: 'general', hinglish: 'general' },

  'glossary.term.deductible.name': { en: 'Deductible', hi: 'डिडक्टिबल', hinglish: 'Deductible' },
  'glossary.term.deductible.hindi': { en: 'डिडक्टिबल / खुद का हिस्सा', hi: 'डिडक्टिबल / खुद का हिस्सा', hinglish: 'Deductible / Khud Ka Hissa' },
  'glossary.term.deductible.explanation': { en: 'Har claim mein se kuch paisa khud dena padta hai', hi: 'हर क्लेम में से कुछ पैसा खुद देना पड़ता है', hinglish: 'Har claim mein se kuch paisa khud dena padta hai' },
  'glossary.term.deductible.example': { en: '₹2,000 deductible = ₹20,000 claim mein ₹18,000 insurance dega', hi: '₹2,000 डिडक्टिबल = ₹20,000 क्लेम में ₹18,000 इंश्योरेंस देगा', hinglish: '₹2,000 deductible = ₹20,000 claim mein ₹18,000 insurance dega' },
  'glossary.term.deductible.category': { en: 'claims', hi: 'claims', hinglish: 'claims' },

  'glossary.term.cashless.name': { en: 'Cashless Claim', hi: 'कैशलेस क्लेम', hinglish: 'Cashless Claim' },
  'glossary.term.cashless.hindi': { en: 'कैशलेस क्लेम', hi: 'कैशलेस क्लेम', hinglish: 'Cashless Claim' },
  'glossary.term.cashless.explanation': { en: 'Hospital/garage mein paisa khud nahi dena, insurance direct pay karega', hi: 'अस्पताल/गैरेज में पैसा खुद नहीं देना, इंश्योरेंस सीधे भुगतान करेगा', hinglish: 'Hospital/garage mein paisa khud nahi dena, insurance direct pay karega' },
  'glossary.term.cashless.example': { en: 'Network hospital mein ₹2L ka operation — tum ₹0 do', hi: 'नेटवर्क अस्पताल में ₹2 लाख का ऑपरेशन — तुम ₹0 दो', hinglish: 'Network hospital mein ₹2L ka operation — tum ₹0 do' },
  'glossary.term.cashless.category': { en: 'claims', hi: 'claims', hinglish: 'claims' },

  'glossary.term.reimbursement.name': { en: 'Reimbursement', hi: 'रीम्बर्समेंट', hinglish: 'Reimbursement' },
  'glossary.term.reimbursement.hindi': { en: 'रीम्बर्समेंट / वापसी', hi: 'रीम्बर्समेंट / वापसी', hinglish: 'Reimbursement / Wapasi' },
  'glossary.term.reimbursement.explanation': { en: 'Pehle khud pay karo, baad mein insurance se refund lo', hi: 'पहले खुद पे करो, बाद में इंश्योरेंस से रिफंड लो', hinglish: 'Pehle khud pay karo, baad mein insurance se refund lo' },
  'glossary.term.reimbursement.example': { en: '₹50,000 ka bill — pehle tum pay, 15 din mein ₹45,000 refund', hi: '₹50,000 का बिल — पहले तुम पे, 15 दिन में ₹45,000 रिफंड', hinglish: '₹50,000 ka bill — pehle tum pay, 15 din mein ₹45,000 refund' },
  'glossary.term.reimbursement.category': { en: 'claims', hi: 'claims', hinglish: 'claims' },

  'glossary.term.waitingPeriod.name': { en: 'Waiting Period', hi: 'वेटिंग पीरियड', hinglish: 'Waiting Period' },
